-- 23/10/2026: motor de copy viral (frente COPY-V). Banco de ganchos vencedores, modelo da copy
-- lembrado por cliente e o padrão "o melhor para copy" no catálogo. Texto dos ganchos é original da
-- Aceleriq (nada copiado de terceiros); chaves {assim} pedem o dado real do cliente.
-- Total do seed: 308 ganchos (odontologia 17, advocacia 17, informatica 17, alimentacao 18, cafe 16, moda 16, varejo 16, saude_estetica 16, imobiliario 16, educacao 16, servicos_locais 16, marketing 17, automotivo 16, eventos 16, moveis_decoracao 16, jardinagem 16, esporte 16, geral 30).

-- 1) Banco de ganchos -------------------------------------------------------------------------------
create table if not exists public.ganchos_vencedores (
  id text primary key,
  formula text not null,
  exemplo text not null,
  por_que_funciona text not null,
  gatilho text not null check (gatilho in ('curiosidade', 'medo_de_perder', 'contrario', 'numero', 'historia', 'prova', 'polemica_leve', 'identificacao')),
  formato text not null check (formato in ('lamina_capa', 'reels_abertura', 'legenda_primeira_linha', 'story', 'anuncio')),
  nichos text[] not null default array['geral']::text[],
  tom text not null default 'direto',
  nivel_de_ousadia smallint not null default 2 check (nivel_de_ousadia between 1 and 3),
  fonte text not null default 'aceleriq_original',
  versao text not null default '2026-10-23.1',
  ativo boolean not null default true,
  criado_em timestamptz not null default now()
);

create index if not exists ganchos_vencedores_nichos_idx on public.ganchos_vencedores using gin (nichos);
create index if not exists ganchos_vencedores_formato_idx on public.ganchos_vencedores (formato, gatilho) where ativo;

alter table public.ganchos_vencedores enable row level security;
revoke all on table public.ganchos_vencedores from public, anon, authenticated;

drop policy if exists ganchos_vencedores_equipe_le on public.ganchos_vencedores;
create policy ganchos_vencedores_equipe_le
on public.ganchos_vencedores
for select to authenticated
using (public.is_staff((select auth.uid())));

grant select on public.ganchos_vencedores to authenticated;
grant select, insert, update, delete on public.ganchos_vencedores to service_role;

on conflict (id) do update set
  formula = excluded.formula,
  exemplo = excluded.exemplo,
  por_que_funciona = excluded.por_que_funciona,
  gatilho = excluded.gatilho,
  formato = excluded.formato,
  nichos = excluded.nichos,
  tom = excluded.tom,
  nivel_de_ousadia = excluded.nivel_de_ousadia,
  versao = excluded.versao;

-- 2) Modelo da copy lembrado por cliente ----------------------------------------------------------
alter table public.mesa_cliente_config add column if not exists modelo_copy_id text;

create or replace function public.definir_modelo_da_copy(_client_id uuid, _modelo_id text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  _uid uuid := auth.uid();
  _id text := nullif(btrim(coalesce(_modelo_id, '')), '');
begin
  if _uid is null or not public.is_staff(_uid) or not public.can_access_client(_client_id) then
    raise exception 'sem_acesso' using errcode = '42501';
  end if;
  if _id is not null and not exists (select 1 from public.ia_modelos m where m.id = _id and m.tipo = 'texto' and m.ativo) then
    raise exception 'modelo_invalido' using errcode = '22023';
  end if;
  values (_client_id, _id, now(), _uid)
  on conflict (client_id) do update set modelo_copy_id = excluded.modelo_copy_id, atualizado_em = now(), atualizado_por = _uid;
  return _id;
end;
$$;

revoke all on function public.definir_modelo_da_copy(uuid, text) from public, anon;
grant execute on function public.definir_modelo_da_copy(uuid, text) to authenticated, service_role;

-- 3) O melhor para copy: Claude Opus 5.5 (escrita em português; já é o padrão de proposta, site e documento).
update public.ia_modelos
set padrao_para = array_append(coalesce(padrao_para, array[]::text[]), 'copy')
where id = 'openrouter:anthropic/claude-opus-5.5'
  and not ('copy' = any(coalesce(padrao_para, array[]::text[])));
